def _segments(text, spans):
    out = []
    for s in spans:
        if isinstance(s, str):
            out.append(s)
        elif isinstance(s, dict):
            if "text" in s:
                out.append(str(s.get("text", "")))
            else:
                a = int(s.get("start", s.get("begin", 0)))
                b = int(s.get("end", s.get("stop", a)))
                out.append(text[a:b])
        elif isinstance(s, (list, tuple)) and len(s) >= 2:
            out.append(text[int(s[0]):int(s[1])])
        else:
            out.append("")
    return out

def _has(s, words):
    return any(w in s for w in words)

def _item(s):
    q = s.strip().lower()
    return q.startswith("(") or (len(q) > 1 and q[0].isalpha() and q[1] in (".", ")"))

def _lead(out, xs, i, words):
    for j in range(max(0, i - 3), i):
        q = xs[j]
        if _has(q, words) and (q.rstrip().endswith(":") or len(q) < 180 or _has(q, ("shall not include", "does not include", "shall not apply", "restrictions", "obligations"))):
            out.add(j)

def _definition(out, xs, i):
    for j in range(max(0, i - 3), i + 1):
        if _has(xs[j], ("confidential information means", "confidential information shall mean", "proprietary information shall", "evaluation material means", "information means")):
            out.add(j)

def _near(xs, i, words, distance):
    return any(_has(xs[j], words) for j in range(max(0, i - distance), min(len(xs), i + distance + 1)))

def propose_members(text, spans, public_hypothesis_key):
    xs = [s.lower() for s in _segments(text, spans)]
    out = set()
    k = public_hypothesis_key
    if k == "nda-11":
        for i, s in enumerate(xs):
            if _has(s, ("reverse engineer", "reverse-engineer", "decompile", "disassemble")):
                out.add(i)
    elif k == "nda-16":
        acts = ("return", "destroy", "delete", "erase", "deliver up", "surrender")
        ends = ("termination", "expiration", "expiry", "completion", "conclusion", "ceases", "ceasing", "abandonment", "does not wish to proceed", "not consummated", "assessment period is over", "end of the term")
        for i, s in enumerate(xs):
            if _has(s, acts) and (_has(s, ends) or _near(xs, i, ends, 3)):
                out.add(i)
                for j in range(max(0, i - 3), min(len(xs), i + 4)):
                    if _has(xs[j], ends) or _has(xs[j], ("written verification", "written certification", "certify", "verification under")):
                        out.add(j)
    elif k == "nda-15":
        for i, s in enumerate(xs):
            if _has(s, ("no license", "no licence", "no right", "no rights", "does not confer", "does not grant", "not be construed as granting", "remain the property", "exclusive property", "sole property", "retain all rights", "reserves all rights", "no title", "no interest")) and _has(s, ("confidential", "information", "intellectual", "property", "right", "license", "licence")):
                out.add(i)
    elif k == "nda-10":
        for i, s in enumerate(xs):
            if _has(s, ("existence of this agreement", "existence and terms", "existence or contents", "fact that discussions", "discussions or negotiations", "discussions and negotiations", "fact that information has been", "subject matter or terms", "public announcement concerning this agreement", "terms of this agreement are confidential")):
                out.add(i)
                _lead(out, xs, i, ("not disclose", "confidential information", "confidential"))
    elif k == "nda-2":
        for i, s in enumerate(xs):
            if _has(s, ("business", "financial", "commercial", "marketing", "customer", "employee", "personnel", "operational", "contractual", "business plans", "all information", "non-technical")) and _has(s, ("confidential information", "proprietary information", "evaluation material", "information shall", "information means", "shall include", "including")):
                out.add(i)
                _definition(out, xs, i)
    elif k == "nda-1":
        for i, s in enumerate(xs):
            if _has(s, ("marked", "mark or label", "designated", "identified as", "identify it in writing", "identified at", "reasonable person", "reasonably understood", "circumstances of disclosure", "nature of the information", "whether or not", "does not need to be marked", "regardless of form", "specifically stated otherwise")) and _has(s, ("confidential", "proprietary", "information", "disclos")):
                out.add(i)
                _definition(out, xs, i)
    elif k == "nda-19":
        for i, s in enumerate(xs):
            if _has(s, ("shall survive", "will survive", "survive termination", "survive expiration", "survive the execution", "continue to be bound", "continue in force", "continue to apply", "remain in effect", "notwithstanding the return", "notwithstanding such return", "after termination", "beyond termination", "continue beyond termination")):
                out.add(i)
    elif k in ("nda-12", "nda-13"):
        words = ("independently developed", "independent development", "developed independently", "independently derived", "developing information internally", "independently create") if k == "nda-12" else ("from a third party", "from third parties", "third party having", "third party who", "another source", "independent source", "source other than", "obtained from others", "received from an independent")
        leads = ("shall not include", "does not include", "shall not apply", "restrictions", "obligations", "exceptions", "excludes", "inoperative")
        for i, s in enumerate(xs):
            if _has(s, words):
                out.add(i)
                _lead(out, xs, i, leads)
    elif k == "nda-20":
        for i, s in enumerate(xs):
            if _has(s, ("return", "destroy", "retain", "retained", "keep one", "archiv", "back-up", "backup", "not required to erase", "not required to delete", "retaining no copies", "without retaining", "infeasible")) and _has(s, ("confidential", "information", "data", "material", "copies", "documents", "records", "property")):
                out.add(i)
                _lead(out, xs, i, ("upon termination", "return of", "return or destruction", "notwithstanding", "upon request"))
    elif k == "nda-3":
        for i, s in enumerate(xs):
            if _has(s, ("oral", "verbally", "spoken", "heard", "regardless of form", "whatever form", "any form whatsoever", "form or medium", "however recorded", "intangible form")) and _has(s, ("information", "disclos", "communicat", "confidential")):
                out.add(i)
                _definition(out, xs, i)
    elif k == "nda-18":
        for i, s in enumerate(xs):
            if _has(s, ("solicit", "induce", "entice", "offer employment", "offer to hire", "employ or retain", "contract for the services")) and _has(s, ("shall not", "will not", "agrees that", "restriction period", "following termination")):
                out.add(i)
                for j in range(i + 1, min(len(xs), i + 7)):
                    if _item(xs[j]) and _has(xs[j], ("solicit", "divert", "take away", "advise", "persuade", "induce", "provide", "accept", "employment", "terminate")):
                        out.add(j)
                    elif len(xs[j].strip()) < 80 and out and not xs[j].strip().endswith("."):
                        out.add(j)
                    else:
                        break
    elif k in ("nda-7", "nda-5"):
        classes = ("employee", "personnel", "staff member") if k == "nda-5" else ("agent", "consultant", "advisor", "adviser", "counsel", "accountant", "contractor", "subcontractor", "representative", "third party", "professional")
        for i, s in enumerate(xs):
            if _has(s, classes) and _has(s, ("disclose", "disclosure", "access", "furnish", "provide", "share", "need to know", "only to", "may disclose", "shall not disclose")):
                out.add(i)
                _lead(out, xs, i, ("may disclose", "only disclose", "shall not disclose", "except", "provided", "agrees"))
    elif k == "nda-17":
        for i, s in enumerate(xs):
            if _has(s, ("make copies", "create copies", "shall not copy", "not copy", "not reproduce", "copy or reproduce", "copies required", "copying", "duplicate or copy", "reduce to writing", "photocopying")) and _has(s, ("confidential", "information", "data", "material", "document")):
                out.add(i)
    elif k == "nda-8":
        for i, s in enumerate(xs):
            if _has(s, ("required by law", "required to disclose", "legally compelled", "court order", "subpoena", "legal process", "governmental authority", "regulatory authority", "operation of law")):
                if _has(s, ("notice", "notify", "consult", "inform", "advise")):
                    out.add(i)
                for j in range(max(0, i - 3), min(len(xs), i + 4)):
                    if _has(xs[j], ("notice", "notify", "consult", "inform", "advise")) and _has(xs[j], ("disclos", "request", "require", "order", "law")):
                        out.add(j)
                        _lead(out, xs, j, ("shall not apply", "does not include", "restrictions", "obligations"))
    elif k == "nda-4":
        for i, s in enumerate(xs):
            if _has(s, ("solely for", "only for", "no purpose other", "not use", "use only", "except for the purpose", "necessary for the purpose", "use the information for", "not to utilise", "not to utilize", "sole purpose")) and _has(s, ("confidential", "information", "data", "material", "purpose", "evaluation", "project")):
                out.add(i)
                _lead(out, xs, i, ("agrees", "undertakes", "shall", "use of"))
    return sorted(out)
